import{f as t,c as n,o as d,aq as a}from"./chunks/framework.D9EfIZ-r.js";const f=JSON.parse('{"title":"Infomanagement-Service","description":"","frontmatter":{},"headers":[],"relativePath":"services/backend-services/infomanagement-service/index.md","filePath":"services/backend-services/infomanagement-service/index.md"}'),r={name:"services/backend-services/infomanagement-service/index.md"};function i(l,e,h,s,o,E){return d(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="infomanagement-service" tabindex="-1">Infomanagement-Service <a class="header-anchor" href="#infomanagement-service" aria-label="Permalink to &quot;Infomanagement-Service&quot;">​</a></h1><p>Dieser Service dient zum Abruf von Konfigurationsinformationen, die für den Betrieb der Software notwendig sind.</p><p>Des Weiteren können bestimmte Konfigurations-Operationen durchgeführt werden.</p><h2 id="abhangigkeiten" tabindex="-1">Abhängigkeiten <a class="header-anchor" href="#abhangigkeiten" aria-label="Permalink to &quot;Abhängigkeiten&quot;">​</a></h2><p>Der Service hat keine Abhängigkeiten zu anderen Services.</p><h2 id="daten-und-funktionen" tabindex="-1">Daten und Funktionen <a class="header-anchor" href="#daten-und-funktionen" aria-label="Permalink to &quot;Daten und Funktionen&quot;">​</a></h2><h3 id="konfigurierter-wahltag" tabindex="-1">Konfigurierter Wahltag <a class="header-anchor" href="#konfigurierter-wahltag" aria-label="Permalink to &quot;Konfigurierter Wahltag&quot;">​</a></h3><p>Der Service verwaltet den konfigurierten Wahltag für eine oder mehrere konkrete Wahlen.</p><h3 id="konfigurationen" tabindex="-1">Konfigurationen <a class="header-anchor" href="#konfigurationen" aria-label="Permalink to &quot;Konfigurationen&quot;">​</a></h3><p>Eine Vielzahl an Konfigurationen wird am Wahltag über das Admin-Tool für die Wahlen festgelegt:</p><table tabindex="0"><thead><tr><th>Schlüssel</th><th>Beschreibung</th><th>Standardwert</th></tr></thead><tbody><tr><td>WLK_TIME_OUT</td><td>Timeout bei Inaktivität</td><td>10800000</td></tr><tr><td>WILLKOMMENSTEXT</td><td>Begrüßungstext auf der Anmeldemaske</td><td>Herzlich Willkommen zur Wahl</td></tr><tr><td>ABSCHLUSSTEXT</td><td>Schlusstext nach Beenden der letzten Wahlhandlung am Wahltag</td><td>Vielen Dank für Ihre Unterstützung als Wahlvorstand.</td></tr><tr><td>WAHLLOKALFINDER_URL</td><td>URL zum Wahllokalfinder der LHM. Leer lassen, um Verknüpfung im WLS auszublenden.</td><td></td></tr><tr><td>FRUEHESTE_LOGIN_UHRZEIT</td><td></td><td></td></tr><tr><td>SPAETESTE_LOGIN_UHRZEIT</td><td></td><td></td></tr><tr><td>FRUEHESTE_EROEFFNUNGSZEIT_UW</td><td>Wahllokal öffnen (UW): Früheste Uhrzeit</td><td>08:00:00</td></tr><tr><td>SPAETESTE_EROEFFNUNGSZEIT_UW</td><td>Wahllokal öffnen (UW): Späteste Uhrzeit</td><td>17:59:00</td></tr><tr><td>FRUEHESTE_SCHLIESSUNGSZEIT_UW</td><td>Wahllokal schließen (UW): Früheste Uhrzeit</td><td>18:00:00</td></tr><tr><td>FRUEHESTE_EROEFFNUNGSZEIT_BW</td><td>Wahllokal öffnen (BW): Früheste Uhrzeit</td><td>15:00:00</td></tr><tr><td>SPAETESTE_EROEFFNUNGSZEIT_BW</td><td>Wahllokal öffnen (BW): Späteste Uhrzeit</td><td>17:59:00</td></tr><tr><td>FRUEHESTE_SCHLIESSUNGSZEIT_BW</td><td>Wahllokal schließen (BW): Früheste Uhrzeit</td><td>18:00:00</td></tr><tr><td>MELDUNGSZEIT_WAHL_SCHLIESSEN</td><td>Automatische Meldung (UW + BW): Wahlhandlung schließen</td><td>18:00:00</td></tr><tr><td>MELDUNGSZEIT_ANWESENHEIT_CHECK</td><td>Automatische Meldung (UW): Anwesenheiten aktualisieren</td><td>13:00:00</td></tr><tr><td>KENNBUCHSTABEN</td><td></td><td>K1, K2, K3 (K1 + K2), K4, K (K3 + K4); L1,L2, L3 (L1 + L2), L4, L (L3 + L4); M1, M2, M3 (M1 + M2), M4, M (M3 + M4); N1, N2, N3 (N1 + N2), N4, N (N3 + N4); O1, O2, O3 (O1 + O2), O4, O OK3 + O4)</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Hinweise zu den Öffnungs- und Schliessungsuhrzeiten</p><ul><li>FRUEHESTE_EROEFFNUNGSZEIT bezeichnet den frühesten Wert, zu dem die Wahlhandlung eröffnet werden kann.</li><li>SPAETESTE_EROEFFNUNGSZEIT bezeichnet den spätesten Wert, zu dem die Wahlhandlung eröffnet werden kann, ohne dass die verspätete Eröffnung als Ereignis dokumentiert werden muss.</li><li>FRUEHESTE_SCHLIESSUNGSZEIT bezeichnet den spätesten Wert, zu dem die Wahlhandlung eröffnet werden kann und den frühesten Wert, zu dem die Wahlhandlung geschlossen werden kann.</li></ul></div>',12)])])}const c=t(r,[["render",i]]);export{f as __pageData,c as default};
